        '</article>';
      }).join("");
    }

    section.classList.add("crays-tech-system-map", "crays-tech-association-stack");
    section.innerHTML = '<div class="crays-tech-shell crays-tech-association-stack__hero">' +
      '<div class="crays-tech-association-stack__intro"><p class="crays-tech-eyebrow">Association technology layer</p><h2 class="crays-tech-title">One backbone keeps official projects compatible.</h2><p class="crays-tech-copy">The Association develops and coordinates the shared technology layer: identity, payments, DAO access, brand rules and venue integration. Approved founders and operators build their own products on top of those rails.</p></div>' +
