(function () {
  function clean(text) {
    return (text || "").replace(/\s+/g, " ").trim();
  }

  function applyThesisLanguage() {
    var thesis = document.querySelector(".crays-tech-thesis");
    if (!thesis) return;

    var thesisTitle = thesis.querySelector(".crays-tech-title");
    if (thesisTitle && clean(thesisTitle.textContent) === "Crays builds the infrastructure that translates intention into economic activity.") {
      thesisTitle.innerHTML = "Crays builds the<br>infrastructure<br>that translates<br>intention into<br>economic activity.";
    }

    var replacements = [
      {
        currentTitle: "Nutzer",
        label: "Intent signals",
        title: "Users"
      },
      {
        currentTitle: "Nachfrage",
        label: "Demand engine",
        title: "Demand"
      },
      {
        currentTitle: "Venues",
        label: "Venue network",
        title: "Venues"
      },
      {
        currentTitle: "Payments",
        label: "Payment rails",
        title: "Payments"
      }
    ];

    replacements.forEach(function (item) {
      var card = Array.from(thesis.querySelectorAll(".crays-tech-mini-card")).find(function (node) {
        var title = node.querySelector("h3");
        return title && clean(title.textContent) === item.currentTitle;
      });

      if (!card) return;

      var kicker = card.querySelector(".crays-tech-kicker");
      var title = card.querySelector("h3");

      if (kicker) kicker.textContent = item.label;
      if (title) title.textContent = item.title;
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", applyThesisLanguage);
  } else {
    applyThesisLanguage();
  }
})();

