(function () {
  function esc(text) {
    return String(text || "").replace(/[&<>"']/g, function (match) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "\"": "&quot;",
        "'": "&#39;"
      }[match];
    });
  }

  function card(item) {
    return '<article class="crays-tech-hospitality-merge__mini"><span>' + esc(item.kicker) + '</span><h4>' + esc(item.title) + '</h4><p>' + esc(item.copy) + '</p></article>';
  }

  function metric(item) {
    return '<article class="crays-tech-hospitality-merge__metric"><span>' + esc(item.kicker) + '</span><strong>' + esc(item.title) + '</strong><p>' + esc(item.copy) + '</p></article>';
  }

  function journey(item) {
    return '<article class="crays-tech-hospitality-merge__journey"><span>' + esc(item.kicker) + '</span><h4>' + esc(item.title) + '</h4><p>' + esc(item.copy) + '</p></article>';
  }

  function chip(label) {
    return '<span class="crays-tech-hospitality-merge__venue-chip">' + esc(label) + '</span>';
  }

  function imageTile(item) {
    return '<figure class="crays-tech-hospitality-merge__image-tile"><img src="' + esc(item.src) + '" alt="' + esc(item.alt) + '" loading="lazy"><figcaption>' + esc(item.caption) + '</figcaption></figure>';
  }

  function panelMedia(item) {
    if (!item.media) return "";
    return '<figure class="crays-tech-hospitality-merge__panel-media"><img src="' + esc(item.media.src) + '" alt="' + esc(item.media.alt) + '" loading="lazy"><figcaption><span>' + esc(item.media.kicker || item.kicker) + '</span><strong>' + esc(item.media.caption) + '</strong></figcaption></figure>';
  }

  function panel(item, index) {
    var active = index === 0;
    var content = "";
    if (item.kind === "journey") {
      content = '<div class="crays-tech-hospitality-merge__journey-grid">' + item.cards.map(journey).join("") + '</div>';
    } else if (item.kind === "metrics") {
      content = '<div class="crays-tech-hospitality-merge__metrics">' + item.cards.map(metric).join("") + '</div>';
    } else {
      content = '<div class="crays-tech-hospitality-merge__mini-grid">' + item.cards.map(card).join("") + '</div>';
    }
    var right = '<div class="crays-tech-hospitality-merge__panel-stack">' + content + '</div>';
    return '<article class="crays-tech-hospitality-merge__panel' + (active ? ' is-active' : '') + '" id="hospitality-infra-panel-' + index + '" role="tabpanel" aria-labelledby="hospitality-infra-tab-' + index + '"' + (active ? '' : ' hidden') + ' tabindex="0">' +
      '<div class="crays-tech-hospitality-merge__panel-grid"><div class="crays-tech-hospitality-merge__panel-copy"><span class="crays-tech-hospitality-merge__kicker">' + esc(item.kicker) + '</span><h3>' + esc(item.title) + '</h3><p>' + esc(item.copy) + '</p>' + (item.chips ? '<div class="crays-tech-hospitality-merge__venue-grid">' + item.chips.map(chip).join("") + '</div>' : '') + panelMedia(item) + '</div>' + right + '</div>' +
    '</article>';
  }

  function renderHospitalityInfrastructure() {
    var main = document.querySelector("main.crays-tech-page");
    if (!main || main.dataset.hospitalityInfrastructureFinal === "true") return;

    var section = main.querySelector(".crays-tech-section--venue");
    if (!section) return;

    main.dataset.hospitalityInfrastructureFinal = "true";
    section.classList.add("crays-tech-hospitality-merge");
    section.id = "hospitality-infrastructure";

    var hero = main.querySelector(".crays-tech-hero");
    var dataSection = main.querySelector(".crays-tech-section--data");
    if (hero && dataSection && hero.nextElementSibling !== dataSection) {
      hero.insertAdjacentElement("afterend", dataSection);
    }

    var sharedRails = main.querySelector(".crays-articles-section--venue-tech");
    var associationProjects = main.querySelector(".crays-tech-section--os");
    if (sharedRails && associationProjects && sharedRails.nextElementSibling !== associationProjects) {
